from typing import Sequence, List, Optional

def _percentile(vals: List[float], p: float) -> float:
    if len(vals) == 1:
        return vals[0]
    idx = p * (len(vals) - 1)
    low = int(idx)
    high = min(low + 1, len(vals) - 1)
    weight = idx - low
    return vals[low] * (1.0 - weight) + vals[high] * weight

class RobustScaler:
    def __init__(self):
        self.medians: List[float] = []
        self.iqrs: List[float] = []

    def fit(self, X: Sequence[Sequence[Optional[float]]]) -> 'RobustScaler':
        n_features = len(X[0])
        self.medians = []
        self.iqrs = []
        for col_idx in range(n_features):
            vals = sorted([row[col_idx] for row in X if row[col_idx] is not None and not math.isnan(row[col_idx])])
            if not vals:
                self.medians.append(0.0)
                self.iqrs.append(1.0)
                continue
            med = _percentile(vals, 0.5)
            q25 = _percentile(vals, 0.25)
            q75 = _percentile(vals, 0.75)
            iqr = q75 - q25
            self.medians.append(med)
            self.iqrs.append(iqr if iqr > 0 else 1.0)
        return self

    def transform(self, X: Sequence[Sequence[Optional[float]]]) -> List[List[float]]:
        res = []
        for row in X:
            scaled_row = []
            for col_idx, val in enumerate(row):
                if val is None or math.isnan(val):
                    scaled_row.append(0.0)
                else:
                    scaled_row.append((val - self.medians[col_idx]) / self.iqrs[col_idx])
            res.append(scaled_row)
        return res

    def inverse_transform(self, X: Sequence[Sequence[float]]) -> List[List[float]]:
        res = []
        for row in X:
            inv_row = []
            for col_idx, val in enumerate(row):
                inv_row.append(val * self.iqrs[col_idx] + self.medians[col_idx])
            res.append(inv_row)
        return res

    def fit_transform(self, X: Sequence[Sequence[Optional[float]]]) -> List[List[float]]:
        return self.fit(X).transform(X)
