        self.fill_values = []
        for col_idx in range(n_features):
            vals = [row[col_idx] for row in X if row[col_idx] is not None and not math.isnan(row[col_idx])]
            if not vals:
                self.fill_values.append(0.0)
                continue
            if self.strategy == 'mean':
                self.fill_values.append(sum(vals) / len(vals))
            elif self.strategy == 'median':
                s = sorted(vals)
                n = len(s)
                self.fill_values.append(s[n // 2] if n % 2 == 1 else (s[n // 2 - 1] + s[n // 2]) / 2.0)
            elif self.strategy == 'most_frequent':
                c = Counter(vals)
                self.fill_values.append(c.most_common(1)[0][0])
            else:
                self.fill_values.append(0.0)
        return self

    def transform(self, X: Sequence[Sequence[Optional[float]]]) -> List[List[float]]:
        res = []
        for row in X:
            r = []
            for col_idx, val in enumerate(row):
                if val is None or math.isnan(val):
                    r.append(self.fill_values[col_idx])
                else:
                    r.append(val)
            res.append(r)
        return res

    def fit_transform(self, X: Sequence[Sequence[Optional[float]]]) -> List[List[float]]:
        return self.fit(X).transform(X)
