from __future__ import annotations
import math
from typing import Sequence

class RobustScaler:
    def __init__(self):
        self.medians: list[float] = []
        self.iqrs: list[float] = []

    def _percentile(self, sorted_vals: list[float], p: float) -> float:
        n = len(sorted_vals)
        if n == 0:
            return 0.0
        idx = p * (n - 1)
        low = math.floor(idx)
        high = math.ceil(idx)
        if low == high:
            return sorted_vals[int(idx)]
        return sorted_vals[low] * (high - idx) + sorted_vals[high] * (idx - low)

    def fit(self, X: Sequence[Sequence[float]]) -> RobustScaler:
        if not X or not X[0]:
            return self
        n_cols = len(X[0])
        self.medians = []
        self.iqrs = []
        for c in range(n_cols):
            col = [X[r][c] for r in range(len(X)) if not math.isnan(X[r][c])]
            col.sort()
            med = self._percentile(col, 0.5)
            q25 = self._percentile(col, 0.25)
            q75 = self._percentile(col, 0.75)
            # BUG: Division by zero when IQR is 0, should default iqr to 1.0
            iqr = q75 - q25
            self.medians.append(med)
            self.iqrs.append(iqr)
        return self

    def transform(self, X: Sequence[Sequence[float]]) -> list[list[float]]:
        out = []
        for row in X:
            out_row = []
            for c, val in enumerate(row):
                scale = self.iqrs[c]
                out_row.append((val - self.medians[c]) / scale)
            out.append(out_row)
        return out

    def fit_transform(self, X: Sequence[Sequence[float]]) -> list[list[float]]:
        return self.fit(X).transform(X)

    def inverse_transform(self, X: Sequence[Sequence[float]]) -> list[list[float]]:
        out = []
        for row in X:
            out.append([row[c] * self.iqrs[c] + self.medians[c] for c in range(len(row))])
        return out
